     1→/**
     2→ * QR Code Generator Service
     3→ *
     4→ * Masa bazli QR kod olusturma ve indirme servisi.
     5→ * QR kodlar menu URL + table_id parametresi icerir.
     6→ *
     7→ * Bu servis hem server-side hem de client-side kullanim icin tasarlanmistir:
     8→ * - Server-side: Buffer olarak QR kod olusturma (PDF, dosya sistemi)
     9→ * - Client-side: Data URL olarak QR kod olusturma ve indirme
    10→ *
    11→ * @example
    12→ * ```ts
    13→ * import { generateTableQRCode, generateMenuUrl, downloadQRCode } from '@/lib/services/qr-generator';
    14→ *
    15→ * // Menu URL olustur
    16→ * const menuUrl = generateMenuUrl('https://ozamenu.com', 'cafe-istanbul', 'uuid-here');
    17→ *
    18→ * // QR kod olustur (Data URL olarak)
    19→ * const dataUrl = await generateTableQRCode({
    20→ *   baseUrl: 'https://ozamenu.com',
    21→ *   organizationSlug: 'cafe-istanbul',
    22→ *   tableId: 'uuid-here',
    23→ *   size: 512
    24→ * });
    25→ *
    26→ * // QR kodu indir (browser'da)
    27→ * downloadQRCode(dataUrl, 'Masa_1.png');
    28→ * ```
    29→ */
    30→
    31→import QRCode from 'qrcode';
    32→import type { UUID } from '@/types';
    33→
    34→// =============================================================================
    35→// TYPES
    36→// =============================================================================
    37→
    38→/**
    39→ * QR kod olusturma secenekleri
    40→ */
    41→export interface QRCodeOptions {
    42→  /** QR kod genisligi piksel cinsinden (varsayilan: 256) */
    43→  width?: number;
    44→  /** QR kod kenar boslugu (varsayilan: 2) */
    45→  margin?: number;
    46→  /** Hata duzeltme seviyesi: L (7%), M (15%), Q (25%), H (30%) (varsayilan: 'M') */
    47→  errorCorrectionLevel?: 'L' | 'M' | 'Q' | 'H';
    48→  /** Koyu renk (varsayilan: '#000000') */
    49→  darkColor?: string;
    50→  /** Acik renk (varsayilan: '#ffffff') */
    51→  lightColor?: string;
    52→}
    53→
    54→/**
    55→ * Masa QR kod olusturma parametreleri
    56→ */
    57→export interface GenerateTableQRParams {
    58→  /** Uygulama base URL'i (ornegin: https://ozamenu.com) */
    59→  baseUrl: string;
    60→  /** Isletme slug'i (ornegin: cafe-istanbul) */
    61→  organizationSlug: string;
    62→  /** Masa UUID'i (qr_uuid) */
    63→  tableId: UUID;
    64→  /** QR kod secenekleri (opsiyonel) */
    65→  options?: QRCodeOptions;
    66→}
    67→
    68→/**
    69→ * Genisletilmis QR kod olusturma parametreleri (boyut eklentili)
    70→ */
    71→export interface GenerateTableQRParamsWithSize extends GenerateTableQRParams {
    72→  /** QR kod boyutu piksel cinsinden (varsayilan: 256) */
    73→  size?: number;
    74→}
    75→
    76→/**
    77→ * Toplu QR kod olusturma icin masa bilgisi
    78→ */
    79→export interface TableQRInfo {
    80→  /** Masa ID'si */
    81→  tableId: UUID;
    82→  /** Masa qr_uuid (QR kodda kullanilir) */
    83→  qrUuid: UUID;
    84→  /** Masa numarasi (dosya adinda kullanilir) */
    85→  tableNumber: string;
    86→  /** Masa ismi (opsiyonel, dosya adinda kullanilir) */
    87→  tableName?: string | null;
    88→}
    89→
    90→/**
    91→ * QR kod sonucu
    92→ */
    93→export interface QRCodeResult {
    94→  /** Basarili olup olmadigini belirtir */
    95→  success: boolean;
    96→  /** Data URL (basarili ise) */
    97→  dataUrl: string | null;
    98→  /** Menu URL */
    99→  menuUrl: string;
   100→  /** Hata mesaji (basarisiz ise) */
   101→  error: string | null;
   102→}
   103→
   104→/**
   105→ * Toplu QR kod sonucu
   106→ */
   107→export interface BulkQRCodeResult {
   108→  /** Masa ID'si */
   109→  tableId: UUID;
   110→  /** QR kod data URL'i */
   111→  dataUrl: string;
   112→  /** Onerilen dosya adi */
   113→  filename: string;
   114→  /** Menu URL */
   115→  menuUrl: string;
   116→}
   117→
   118→// =============================================================================
   119→// CONSTANTS
   120→// =============================================================================
   121→
   122→/** Varsayilan QR kod secenekleri */
   123→const DEFAULT_QR_OPTIONS: Required<QRCodeOptions> = {
   124→  width: 256,
   125→  margin: 2,
   126→  errorCorrectionLevel: 'M',
   127→  darkColor: '#000000',
   128→  lightColor: '#ffffff',
   129→};
   130→
   131→/** Yuksek cozunurluklu QR kod icin boyut */
   132→export const HIGH_RES_SIZE = 512;
   133→
   134→/** Standart QR kod icin boyut */
   135→export const STANDARD_SIZE = 256;
   136→
   137→/** Kucuk QR kod icin boyut (onizleme) */
   138→export const PREVIEW_SIZE = 128;
   139→
   140→// =============================================================================
   141→// URL GENERATION
   142→// =============================================================================
   143→
   144→/**
   145→ * Menu URL'i olusturur.
   146→ *
   147→ * Format: {baseUrl}/menu/{organizationSlug}?table_id={tableId}
   148→ *
   149→ * @param baseUrl - Uygulama base URL'i
   150→ * @param organizationSlug - Isletme slug'i
   151→ * @param tableId - Masa UUID'i (qr_uuid)
   152→ * @returns Menu URL'i
   153→ *
   154→ * @example
   155→ * ```ts
   156→ * const url = generateMenuUrl('https://ozamenu.com', 'cafe-istanbul', 'abc-123');
   157→ * // => 'https://ozamenu.com/menu/cafe-istanbul?table_id=abc-123'
   158→ * ```
   159→ */
   160→export function generateMenuUrl(
   161→  baseUrl: string,
   162→  organizationSlug: string,
   163→  tableId: string
   164→): string {
   165→  // URL'den trailing slash'leri temizle
   166→  const cleanBaseUrl = baseUrl.replace(/\/+$/, '');
   167→  // Slug'i encode et (ozel karakterler icin)
   168→  const encodedSlug = encodeURIComponent(organizationSlug);
   169→  // Table ID'yi encode et (UUID'ler icin guvenli)
   170→  const encodedTableId = encodeURIComponent(tableId);
   171→
   172→  return `${cleanBaseUrl}/menu/${encodedSlug}?table_id=${encodedTableId}`;
   173→}
   174→
   175→/**
   176→ * Sadece menu URL'i olusturur (masa ID'siz).
   177→ *
   178→ * @param baseUrl - Uygulama base URL'i
   179→ * @param organizationSlug - Isletme slug'i
   180→ * @returns Menu URL'i
   181→ */
   182→export function generateMenuUrlWithoutTable(
   183→  baseUrl: string,
   184→  organizationSlug: string
   185→): string {
   186→  const cleanBaseUrl = baseUrl.replace(/\/+$/, '');
   187→  const encodedSlug = encodeURIComponent(organizationSlug);
   188→  return `${cleanBaseUrl}/menu/${encodedSlug}`;
   189→}
   190→
   191→// =============================================================================
   192→// QR CODE GENERATION - DATA URL
   193→// =============================================================================
   194→
   195→/**
   196→ * QR kod olusturur (Data URL olarak).
   197→ *
   198→ * Data URL, img src'de veya indirme icin kullanilabilir.
   199→ * Client-side ve server-side'da calisir.
   200→ *
   201→ * @param url - QR kodun icerecegi URL
   202→ * @param options - QR kod secenekleri
   203→ * @returns Promise<string> - Base64 Data URL
   204→ *
   205→ * @example
   206→ * ```ts
   207→ * const dataUrl = await generateQRCodeDataUrl('https://example.com/menu/cafe?table_id=123');
   208→ * // => 'data:image/png;base64,iVBORw0KGgo...'
   209→ * ```
   210→ */
   211→export async function generateQRCodeDataUrl(
   212→  url: string,
   213→  options: QRCodeOptions = {}
   214→): Promise<string> {
   215→  const mergedOptions = { ...DEFAULT_QR_OPTIONS, ...options };
   216→
   217→  return QRCode.toDataURL(url, {
   218→    width: mergedOptions.width,
   219→    margin: mergedOptions.margin,
   220→    errorCorrectionLevel: mergedOptions.errorCorrectionLevel,
   221→    color: {
   222→      dark: mergedOptions.darkColor,
   223→      light: mergedOptions.lightColor,
   224→    },
   225→  });
   226→}
   227→
   228→/**
   229→ * Masa icin QR kod olusturur (Data URL olarak).
   230→ *
   231→ * @param params - QR kod parametreleri
   232→ * @returns Promise<QRCodeResult> - QR kod sonucu
   233→ *
   234→ * @example
   235→ * ```ts
   236→ * const result = await generateTableQRCode({
   237→ *   baseUrl: 'https://ozamenu.com',
   238→ *   organizationSlug: 'cafe-istanbul',
   239→ *   tableId: 'uuid-here',
   240→ *   options: { width: 512, errorCorrectionLevel: 'H' }
   241→ * });
   242→ *
   243→ * if (result.success) {
   244→ *   console.log(result.dataUrl);
   245→ * }
   246→ * ```
   247→ */
   248→export async function generateTableQRCode(
   249→  params: GenerateTableQRParams
   250→): Promise<QRCodeResult> {
   251→  const { baseUrl, organizationSlug, tableId, options = {} } = params;
   252→
   253→  // Validate parameters
   254→  if (!baseUrl) {
   255→    return {
   256→      success: false,
   257→      dataUrl: null,
   258→      menuUrl: '',
   259→      error: 'Base URL gereklidir',
   260→    };
   261→  }
   262→
   263→  if (!organizationSlug) {
   264→    return {
   265→      success: false,
   266→      dataUrl: null,
   267→      menuUrl: '',
   268→      error: 'Isletme slug\'i gereklidir',
   269→    };
   270→  }
   271→
   272→  if (!tableId) {
   273→    return {
   274→      success: false,
   275→      dataUrl: null,
   276→      menuUrl: '',
   277→      error: 'Masa ID\'si gereklidir',
   278→    };
   279→  }
   280→
   281→  try {
   282→    const menuUrl = generateMenuUrl(baseUrl, organizationSlug, tableId);
   283→    const dataUrl = await generateQRCodeDataUrl(menuUrl, options);
   284→
   285→    return {
   286→      success: true,
   287→      dataUrl,
   288→      menuUrl,
   289→      error: null,
   290→    };
   291→  } catch (error) {
   292→    return {
   293→      success: false,
   294→      dataUrl: null,
   295→      menuUrl: generateMenuUrl(baseUrl, organizationSlug, tableId),
   296→      error: error instanceof Error ? error.message : 'QR kod olusturulamadi',
   297→    };
   298→  }
   299→}
   300→
   301→/**
   302→ * Basitlestirilmis masa QR kodu olusturma fonksiyonu.
   303→ *
   304→ * @param baseUrl - Uygulama base URL'i
   305→ * @param organizationSlug - Isletme slug'i
   306→ * @param tableId - Masa UUID'i
