     1→/**
     2→ * Snapshot Service
     3→ *
     4→ * Menu snapshot (anlık görüntü) yönetimi için servis modülü.
     5→ * Bu modül, menü durumunu (ürünler + güncel fiyatlar) JSON olarak yakalayıp
     6→ * menu_snapshots tablosuna saklar.
     7→ *
     8→ * CRITICAL: Menu snapshot'ları yasal uyumluluk için IMMUTABLE'dır!
     9→ * Bu tabloya UPDATE ve DELETE yapılamaz (database trigger ile engellenir).
    10→ *
    11→ * İş Akışı:
    12→ * 1. Tüm aktif ürünleri ve güncel fiyatlarını getir
    13→ * 2. JSON snapshot oluştur
    14→ * 3. SHA-256 hash hesapla
    15→ * 4. menu_snapshots tablosuna INSERT et
    16→ *
    17→ * @example
    18→ * ```ts
    19→ * import { createMenuSnapshot, getLatestSnapshot, verifySnapshotHash } from '@/lib/services/snapshot';
    20→ *
    21→ * // Menü snapshot'ı oluştur
    22→ * const result = await createMenuSnapshot(organizationId);
    23→ *
    24→ * // Son snapshot'ı getir
    25→ * const latest = await getLatestSnapshot(organizationId);
    26→ *
    27→ * // Hash doğrula
    28→ * const isValid = await verifySnapshotHash(snapshotId);
    29→ * ```
    30→ */
    31→
    32→import { createHash } from 'crypto';
    33→import { createServerSupabaseClient } from '@/lib/supabase/server';
    34→import type {
    35→  UUID,
    36→  CurrencyCode,
    37→  MenuSnapshot,
    38→  MenuSnapshotData,
    39→  MenuSnapshotProduct,
    40→  MenuSnapshotInsert,
    41→} from '@/types';
    42→
    43→// =============================================================================
    44→// TYPES
    45→// =============================================================================
    46→
    47→/**
    48→ * Snapshot creation result
    49→ */
    50→export interface CreateSnapshotResult {
    51→  /** Whether the operation was successful */
    52→  success: boolean;
    53→  /** The created snapshot ID */
    54→  snapshotId: UUID | null;
    55→  /** The SHA-256 hash of the snapshot */
    56→  hash: string | null;
    57→  /** Number of products included in the snapshot */
    58→  productCount: number;
    59→  /** Error message if operation failed */
    60→  error: string | null;
    61→}
    62→
    63→/**
    64→ * Snapshot with verification status
    65→ */
    66→export interface SnapshotWithVerification extends MenuSnapshot {
    67→  /** Whether the stored hash matches the computed hash */
    68→  isValid: boolean;
    69→  /** The recomputed hash for comparison */
    70→  computedHash: string;
    71→}
    72→
    73→/**
    74→ * Snapshot summary for listing
    75→ */
    76→export interface SnapshotSummary {
    77→  id: UUID;
    78→  createdAt: Date;
    79→  productCount: number;
    80→  hash: string;
    81→  triggeredByPriceChange: boolean;
    82→}
    83→
    84→/**
    85→ * Product data used in snapshot creation (from view)
    86→ */
    87→interface ProductWithCurrentPrice {
    88→  id: UUID;
    89→  name: string;
    90→  current_price: number | null;
    91→  current_currency: CurrencyCode | null;
    92→  category_name: string | null;
    93→  is_active: boolean;
    94→  organization_id: UUID;
    95→}
    96→
    97→// =============================================================================
    98→// HASH COMPUTATION
    99→// =============================================================================
   100→
   101→/**
   102→ * Compute SHA-256 hash of a snapshot data object.
   103→ *
   104→ * CRITICAL: The hash is computed from the stringified JSON.
   105→ * The same JSON structure must produce the same hash for verification.
   106→ *
   107→ * @param data - The menu snapshot data
   108→ * @returns SHA-256 hash as 64 character hex string
   109→ */
   110→export function computeSnapshotHash(data: MenuSnapshotData): string {
   111→  const jsonString = JSON.stringify(data);
   112→  return createHash('sha256').update(jsonString).digest('hex');
   113→}
   114→
   115→/**
   116→ * Validate SHA-256 hash format.
   117→ *
   118→ * @param hash - The hash to validate
   119→ * @returns True if hash is valid 64-character hex string
   120→ */
   121→export function isValidHashFormat(hash: string): boolean {
   122→  return /^[a-f0-9]{64}$/.test(hash);
   123→}
   124→
   125→// =============================================================================
   126→// MAIN FUNCTIONS
   127→// =============================================================================
   128→
   129→/**
   130→ * Create a menu snapshot for an organization.
   131→ *
   132→ * Captures the complete menu state (all active products with current prices)
   133→ * and stores it in the menu_snapshots table with a SHA-256 hash.
   134→ *
   135→ * @param organizationId - The organization UUID
