   154→export async function createMenuSnapshot(
   155→  organizationId: UUID,
   156→  triggeredByPriceLedgerId?: UUID | null
   157→): Promise<CreateSnapshotResult> {
   158→  const supabase = await createServerSupabaseClient();
   159→
   160→  // Validate organization exists
   161→  const { data: org, error: orgError } = await supabase
   162→    .from('organizations')
   163→    .select('id')
   164→    .eq('id', organizationId)
   165→    .single();
