   170→      snapshotId: null,
   171→      hash: null,
   172→      productCount: 0,
   173→      error: 'İşletme bulunamadı',
   174→    };
   175→  }
   176→
   177→  // Get all active products with current prices using the view
   178→  const { data: products, error: productsError } = await supabase
   179→    .from('products_with_current_price')
   180→    .select('id, name, current_price, current_currency, category_name, is_active, organization_id')
   181→    .eq('organization_id', organizationId)
