    15→ * @see https://supabase.com/docs/guides/auth/signout
    16→ */
    17→
    18→import { createServerClient } from '@supabase/ssr';
    19→import { cookies } from 'next/headers';
    20→import { NextResponse, type NextRequest } from 'next/server';
    21→
    22→/**
    23→ * POST /api/auth/logout
    24→ *
    25→ * Oturumu sonlandirir ve JSON response doner.
    26→ * Client-side JavaScript ile kullanim icin uygundur.
    27→ *
    28→ * @param request - Incoming request
    29→ * @returns JSON response with success status
    30→ */
    31→// eslint-disable-next-line @typescript-eslint/no-unused-vars
    32→export async function POST(request: NextRequest) {
    33→  const cookieStore = await cookies();
    34→
    35→  // Supabase client olustur (route handler icin ozel)
    36→  const supabase = createServerClient(
    37→    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    38→    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    39→    {
    40→      cookies: {
    41→        getAll() {
    42→          return cookieStore.getAll();
    43→        },
    44→        setAll(cookiesToSet) {
    45→          try {
    46→            cookiesToSet.forEach(({ name, value, options }) =>
    47→              cookieStore.set(name, value, options)
    48→            );
    49→          } catch {
    50→            // Cookie yazimi basarisiz olabilir, middleware tarafindan set edilir.
    51→          }
    52→        },
    53→      },
    54→    }
    55→  );
    56→
    57→  // Oturumu sonlandir
    58→  const { error } = await supabase.auth.signOut();
    59→
    60→  if (error) {
    61→    return NextResponse.json(
    62→      {
    63→        success: false,
    64→        error: 'Oturum kapatilirken bir hata olustu.',
    65→        details: error.message,
    66→      },
    67→      { status: 500 }
    68→    );
    69→  }
    70→
    71→  // Basarili cikis
    72→  return NextResponse.json({
    73→    success: true,
    74→    message: 'Oturum basariyla kapatildi.',
    75→    redirectTo: '/',
    76→  });
    77→}
