   140→    .from('locations')
   141→    .select('*')
   142→    .eq('organization_id', org.id)
   143→    .eq('slug', locationSlug)
   144→    .eq('is_active', true)
   145→    .single();
   146→
   147→  if (locError || !location) {
   148→    return null;
